// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(address actor, uint64 t, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(log));
        amount = bound(amount, 1 ether, 1000 ether);
        t = uint64(bound(uint256(t), 1, type(uint64).max / 2));

        vm.warp(t);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // Rule: the deposit made at time t must be recorded in the Log with Time == t.
        bool ok = false;
        try log.History(log.History.length - 1) returns (
            address /*sender*/, string memory /*data*/, uint256 /*val*/, uint256 time
        ) {
            ok = (time == t);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

