pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log history;

    function setUp() public {
        history = new Log();
        c = new C(address(history));
    }

    // Count History entries by probing the public getter until out of bounds.
    function _historyCount() internal view returns (uint256 n) {
        for (uint256 i = 0; ; i++) {
            try history.History(i) returns (address, string memory, uint256, uint256) {
                n = i + 1;
            } catch {
                return n;
            }
        }
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, c.MinDeposit(), 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // General rule: any deposit of at least MinDeposit is always recorded
        // in the Log's History, so exactly one entry must exist afterwards.
        assertTrue(_historyCount() == 1);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function check(uint amount) public {
        require(amount >= c.MinDeposit());
        require(address(this).balance >= amount);
        c.Deposit{value: amount}();
        assert(c.balances(address(this)) == amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

